<template><section class="content-card"><div class="page-title"><div><p class="eyebrow">ЗАПИСЬ ПО ТЕЛЕФОНУ</p><h1>Записать клиента</h1><p>Выберите клиента, услугу, мастера и свободное время.</p></div></div><div class="admin-booking-form"><label>Клиент<select v-model="clientId" class="native-input"><option disabled value="">Выберите клиента</option><option v-for="c in clients" :key="c.id" :value="c.id">{{c.fio}} — {{c.telefon}}</option></select></label><label>Услуга<select v-model="serviceId" class="native-input" @change="loadMasters"><option disabled value="">Выберите услугу</option><option v-for="s in services" :key="s.id" :value="s.id">{{s.nazvanie}} — {{s.stoimost}} ₽</option></select></label><label>Мастер<select v-model="masterId" class="native-input" @change="loadSlots"><option disabled value="">Выберите мастера</option><option v-for="m in masters" :key="m.id" :value="m.id">{{m.fio}}</option></select></label><label>Дата<input v-model="date" class="native-input" type="date" :min="today" @change="loadSlots"></label></div><h3 v-if="date && masterId">Свободное время</h3><div class="slots"><Button v-for="slot in slots" :key="slot" :label="slot" :outlined="time!==slot" @click="time=slot"/></div><Message v-if="date && masterId && !slots.length" severity="info" :closable="false">На выбранный день свободного времени нет.</Message><Message v-if="error" severity="error" :closable="false">{{error}}</Message><div class="actions"><Button label="Отмена" severity="secondary" @click="$router.push('/seans')"/><Button label="Создать и подтвердить запись" icon="pi pi-check" :disabled="!ready" @click="save"/></div></section></template>
<script>import Button from'primevue/button';import Message from'primevue/message';import{useDataStore}from'@/stores/dataStore';export default{components:{Button,Message},data:()=>({store:useDataStore(),clients:[],services:[],masters:[],slots:[],clientId:'',serviceId:'',masterId:'',date:'',time:'',error:''}),computed:{today(){return new Date().toISOString().slice(0,10)},ready(){return this.clientId&&this.serviceId&&this.masterId&&this.date&&this.time}},async mounted(){await this.store.get_klient(0,100);this.clients=this.store.klient;this.services=await this.store.get_bookable_services();if(this.$route.query.client)this.clientId=Number(this.$route.query.client)},methods:{async loadMasters(){this.masterId='';this.time='';this.slots=[];this.masters=await this.store.get_masters_for_service(this.serviceId)},async loadSlots(){this.time='';if(this.serviceId&&this.masterId&&this.date)this.slots=await this.store.get_available_slots(this.serviceId,this.masterId,this.date)},async save(){try{await this.store.create_admin_booking({klient_id:this.clientId,usluga_id:this.serviceId,kosmetolog_id:this.masterId,date:this.date,time:this.time});this.$toast.add({severity:'success',summary:'Клиент записан',detail:'Запись сразу подтверждена',life:3000});this.$router.push('/seans')}catch(e){this.error=e.response?.data?.message||'Не удалось создать запись'}}}}</script>
